## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/masldLogic.ts`

```typescript
/**
 * MASLD / MASH Clinical Logic Engine
 * Based on: AGA Clinical Practice Update on MASLD/MASH (2024–2025)
 *           ACG Clinical Guideline: NAFLD/MASLD (2023, 2025 Update)
 *           AASLD Practice Guidance on MASH (2023)
 *           Resmetirom (Rezdiffra) FDA approval for MASH with F2–F3 fibrosis (March 2024)
 * Key decisions: Noninvasive fibrosis staging, cardiometabolic risk, pharmacotherapy
 *                (resmetirom, semaglutide, pioglitazone), liver biopsy indication, transplant evaluation
 */

export type MASLDRisk = 'low' | 'intermediate' | 'high';
export type FibrosisStage = 'F0' | 'F1' | 'F2' | 'F3' | 'F4_cirrhosis';
export type MASHStatus = 'no_mash' | 'suspected_mash' | 'biopsy_confirmed_mash';
export type DiabetesStatus = 'none' | 'prediabetes' | 'type2_diabetes';

export interface MASLDInput {
  // Diagnosis
  hasLiverSteatosis: boolean; // confirmed by imaging or biopsy
  steatosisMethod: 'ultrasound' | 'ct' | 'mri_pdff' | 'biopsy' | 'cap_score';
  mashStatus: MASHStatus;

  // Noninvasive fibrosis assessment
  fib4Score?: number; // Fibrosis-4 index (age × AST / [PLT × √ALT])
  nfsScore?: number; // NAFLD Fibrosis Score
  lsm_kPa?: number; // Liver stiffness measurement (kPa) by FibroScan
  mriElastography_kPa?: number;
  estimatedFibrosisStage: FibrosisStage;

  // Cardiometabolic risk factors
  bmi?: number;
  diabetesStatus: DiabetesStatus;
  hasHypertension: boolean;
  hasDyslipidemia: boolean;
  hasMetabolicSyndrome: boolean;
  hasCardiovascularDisease: boolean;
  hasObesity: boolean; // BMI ≥30

  // Liver disease severity
  hasCirchosis: boolean;
  hasPortalHypertension: boolean;
  hasEsophagealVarices: boolean;
  hasAscites: boolean;
  hasHepaticEncephalopathy: boolean;
  hasHCC: boolean;
  childPughScore?: 'A' | 'B' | 'C';
  meldScore?: number;

  // Current medications
  isOnMetformin: boolean;
  isOnGLP1Agonist: boolean; // semaglutide, liraglutide, tirzepatide
  isOnPioglitazone: boolean;
  isOnStatin: boolean;
  isOnVitaminE: boolean;

  // Lifestyle
  alcoholUseGramsPerDay?: number; // >20g/day women, >30g/day men = ALD not MASLD
  hasSobietyFromAlcohol: boolean;
  physicalActivityMinPerWeek?: number;
  weightLossPercentRecent?: number; // % body weight lost in past 6 months

  // Transplant evaluation
  isEvaluatedForTransplant: boolean;
}

export interface MASLDRecommendation {
  primaryRecommendation: string;
  fibrosisAssessment: string;
  pharmacotherapy: string;
  liverBiopsyIndication: string;
  cardiometabolicManagement: string;
  lifestyleInterventions: string;
  surveillancePlan: string;
  transplantConsideration: string;
  urgentFlags: string[];
  recommendedAgents: string[];
  nextSteps: string[];
  evidenceLevel: 'A' | 'B' | 'C';
  rationale: string;
  references: Array<{ citation: string; pmid?: string; url?: string }>;
}

export function assessMASLD(input: MASLDInput): MASLDRecommendation {
  const urgentFlags: string[] = [];
  const recommendedAgents: string[] = [];
  const nextSteps: string[] = [];

  // ─── Urgent Flags ─────────────────────────────────────────────────────────
  if (input.hasHCC) {
    urgentFlags.push('HEPATOCELLULAR CARCINOMA: multidisciplinary liver tumor board review required — staging and treatment planning');
  }
  if (input.hasAscites || input.hasHepaticEncephalopathy) {
    urgentFlags.push('DECOMPENSATED CIRRHOSIS: hepatology referral urgently — liver transplant evaluation, SBP prophylaxis, lactulose/rifaximin');
  }
  if (input.meldScore !== undefined && input.meldScore >= 15) {
    urgentFlags.push(`MELD score ${input.meldScore} ≥15: liver transplant evaluation recommended — refer to transplant center`);
  }
  if (input.hasEsophagealVarices) {
    urgentFlags.push('Esophageal varices: non-selective beta-blocker (propranolol/carvedilol) for primary prophylaxis; EGD surveillance every 1–3 years');
  }
  if (input.alcoholUseGramsPerDay !== undefined && input.alcoholUseGramsPerDay > 20) {
    urgentFlags.push(`Significant alcohol use (${input.alcoholUseGramsPerDay}g/day): diagnosis may be ALD or mixed ALD/MASLD — alcohol cessation counseling required before MASLD pharmacotherapy`);
  }

  // ─── Fibrosis Assessment ──────────────────────────────────────────────────
  let fibrosisAssessment = '';
  let fibrosisRisk: MASLDRisk = 'low';

  if (input.fib4Score !== undefined) {
    if (input.fib4Score < 1.3) {
      fibrosisRisk = 'low';
      fibrosisAssessment = `FIB-4 ${input.fib4Score.toFixed(2)} (<1.3): LOW risk of advanced fibrosis. No further fibrosis testing needed in low-risk patients. Reassess FIB-4 every 1–2 years.`;
    } else if (input.fib4Score <= 2.67) {
      fibrosisRisk = 'intermediate';
      fibrosisAssessment = `FIB-4 ${input.fib4Score.toFixed(2)} (1.3–2.67): INTERMEDIATE risk. Proceed to secondary noninvasive test — FibroScan (LSM) or ELF score. Consider liver biopsy if secondary test indeterminate.`;
      nextSteps.push('FibroScan (vibration-controlled transient elastography) for liver stiffness measurement', 'Consider ELF (Enhanced Liver Fibrosis) score');
    } else {
      fibrosisRisk = 'high';
      fibrosisAssessment = `FIB-4 ${input.fib4Score.toFixed(2)} (>2.67): HIGH risk of advanced fibrosis (F3–F4). Hepatology referral + liver biopsy or advanced imaging (MR elastography) recommended.`;
      nextSteps.push('Hepatology referral', 'Liver biopsy or MR elastography for fibrosis staging', 'HCC surveillance if cirrhosis confirmed');
    }
  } else if (input.lsm_kPa !== undefined) {
    if (input.lsm_kPa < 8) {
      fibrosisRisk = 'low';
      fibrosisAssessment = `FibroScan LSM ${input.lsm_kPa}kPa (<8kPa): LOW risk of advanced fibrosis (F0–F1). Annual monitoring with FIB-4.`;
    } else if (input.lsm_kPa < 12) {
      fibrosisRisk = 'intermediate';
      fibrosisAssessment = `FibroScan LSM ${input.lsm_kPa}kPa (8–12kPa): INTERMEDIATE — may have F2–F3 fibrosis. Consider liver biopsy for definitive staging.`;
    } else {
      fibrosisRisk = 'high';
      fibrosisAssessment = `FibroScan LSM ${input.lsm_kPa}kPa (≥12kPa): HIGH risk — likely F3–F4 fibrosis or cirrhosis. Hepatology referral + HCC surveillance.`;
      urgentFlags.push('FibroScan LSM ≥12kPa: likely advanced fibrosis/cirrhosis — hepatology referral and HCC surveillance required');
    }
  } else {
    fibrosisAssessment =
      'Noninvasive fibrosis assessment not yet performed. ' +
      'RECOMMENDED PATHWAY (AGA 2024): ' +
      'Step 1: Calculate FIB-4 index (age × AST / [PLT × √ALT]). ' +
      'Step 2: If FIB-4 1.3–2.67 → FibroScan or ELF score. ' +
      'Step 3: If high risk on secondary test → hepatology referral ± liver biopsy.';
    nextSteps.push('Calculate FIB-4 index (requires age, AST, ALT, platelet count)', 'FibroScan if FIB-4 intermediate (1.3–2.67)');
  }

  // ─── Pharmacotherapy ──────────────────────────────────────────────────────
  let pharmacotherapy = '';
  const isPharmacotherapyCandidate =
    input.mashStatus === 'biopsy_confirmed_mash' ||
    (input.estimatedFibrosisStage === 'F2' || input.estimatedFibrosisStage === 'F3') ||
    fibrosisRisk === 'high';

  if (input.hasCirchosis && input.childPughScore === 'C') {
    pharmacotherapy =
      'Decompensated cirrhosis (Child-Pugh C): pharmacotherapy for MASH is not the priority. ' +
      'Focus on liver transplant evaluation, management of complications (ascites, varices, HE). ' +
      'Avoid hepatotoxic medications.';
  } else if (isPharmacotherapyCandidate || (input.mashStatus === 'suspected_mash' && fibrosisRisk !== 'low')) {
    pharmacotherapy =
      'PHARMACOTHERAPY FOR MASH WITH SIGNIFICANT FIBROSIS (F2–F3): ' +
      '1) RESMETIROM (Rezdiffra) 80–100mg QD — FIRST FDA-APPROVED MASH DRUG (March 2024). ' +
      '   THRβ agonist. MAESTRO-NASH trial: 26% MASH resolution without fibrosis worsening at 52 weeks. ' +
      '   Indicated for MASH with moderate-to-advanced fibrosis (F2–F3) in adults. ' +
      '   Dose: 80mg/day (BMI <35) or 100mg/day (BMI ≥35). ' +
      '   Avoid with moderate-severe hepatic impairment (Child-Pugh B/C). ' +
      '2) SEMAGLUTIDE (Ozempic/Wegovy) — GLP-1 agonist: MASH resolution in 59% (NASH CRN phase 2). ' +
      '   Phase 3 ESSENCE trial (semaglutide 2.4mg) results expected 2025. ' +
      '   Also addresses cardiometabolic comorbidities (T2DM, obesity, CV risk). ' +
      '3) TIRZEPATIDE (Mounjaro/Zepbound) — GLP-1/GIP dual agonist: SYNERGY-NASH trial ongoing. ' +
      '   Significant weight loss (>20%) and metabolic benefit. ' +
      '4) PIOGLITAZONE (Actos) — TZD: PIVENS trial: MASH resolution in 47% (non-diabetic). ' +
      '   Effective for MASH ± T2DM. Caution: weight gain, fluid retention, bladder cancer risk. ' +
      '5) VITAMIN E 800 IU/day — PIVENS trial: MASH resolution in 43% (non-diabetic, non-cirrhotic). ' +
      '   Avoid in men (prostate cancer risk), diabetics, and cirrhosis.';
    recommendedAgents.push(
      'Resmetirom 80–100mg QD (FDA-approved for MASH F2–F3 — MAESTRO-NASH)',
      'Semaglutide 2.4mg SC weekly (GLP-1 — ESSENCE trial pending)',
      'Tirzepatide 15mg SC weekly (GLP-1/GIP — SYNERGY-NASH)',
      'Pioglitazone 30–45mg QD (TZD — PIVENS trial)',
      'Vitamin E 800 IU/day (non-diabetic, non-cirrhotic only)'
    );
  } else if (input.estimatedFibrosisStage === 'F0' || input.estimatedFibrosisStage === 'F1') {
    pharmacotherapy =
      'MASLD without significant fibrosis (F0–F1): pharmacotherapy not routinely indicated. ' +
      'Lifestyle modification is the cornerstone of treatment. ' +
      'GLP-1 agonists (semaglutide, tirzepatide) are appropriate if T2DM or obesity present. ' +
      'Reassess fibrosis annually with FIB-4.';
    if (input.diabetesStatus === 'type2_diabetes' || input.hasObesity) {
      recommendedAgents.push(
        'Semaglutide (Ozempic 1mg SC weekly for T2DM; Wegovy 2.4mg SC weekly for obesity)',
        'Tirzepatide (Mounjaro for T2DM; Zepbound for obesity)',
        'Metformin (T2DM — neutral effect on MASH but addresses cardiometabolic risk)'
      );
    }
  } else {
    pharmacotherapy =
      'Fibrosis stage not definitively established. Complete noninvasive fibrosis assessment before initiating MASH-specific pharmacotherapy.';
  }

  // ─── Liver Biopsy Indication ──────────────────────────────────────────────
  let liverBiopsyIndication = '';
  if (fibrosisRisk === 'high' || input.fib4Score !== undefined && input.fib4Score > 2.67) {
    liverBiopsyIndication =
      'Liver biopsy INDICATED (AGA 2024): ' +
      'High-risk noninvasive fibrosis assessment (FIB-4 >2.67 or LSM ≥12kPa). ' +
      'Biopsy provides definitive MASH diagnosis and fibrosis staging. ' +
      'Required before initiating resmetirom (FDA label requires MASH diagnosis). ' +
      'Consider MR elastography as alternative to biopsy for fibrosis staging.';
    nextSteps.push('Liver biopsy or MR elastography for definitive MASH diagnosis and fibrosis staging');
  } else if (fibrosisRisk === 'intermediate') {
    liverBiopsyIndication =
      'Liver biopsy CONSIDER (AGA 2024): ' +
      'Intermediate-risk noninvasive assessment. ' +
      'Biopsy indicated if secondary noninvasive test (FibroScan, ELF) also indeterminate. ' +
      'Biopsy required if pharmacotherapy (resmetirom) planned.';
  } else {
    liverBiopsyIndication =
      'Liver biopsy NOT routinely indicated for low-risk MASLD (FIB-4 <1.3). ' +
      'Reassess with FIB-4 every 1–2 years.';
  }

  // ─── Cardiometabolic Management ───────────────────────────────────────────
  const cardiometabolicManagement =
    'CARDIOMETABOLIC MANAGEMENT (AGA 2024 — cardiovascular disease is the leading cause of death in MASLD): ' +
    '1) Statin therapy: safe in MASLD/MASH — may reduce liver inflammation. Use for CV risk reduction per ACC/AHA guidelines. ' +
    '2) GLP-1 agonists: address T2DM, obesity, and MASH simultaneously — preferred in T2DM + MASLD. ' +
    '3) SGLT2 inhibitors (empagliflozin, dapagliflozin): CV benefit + potential MASH benefit (EMPA-LIVER trial). ' +
    '4) Blood pressure control: target <130/80 mmHg. ' +
    '5) Dyslipidemia: statin + ezetimibe if needed. ' +
    '6) Aspirin: per CV risk guidelines.';

  if (!input.isOnStatin && input.hasCardiovascularDisease) {
    recommendedAgents.push('High-intensity statin (atorvastatin 40–80mg or rosuvastatin 20–40mg) — safe in MASLD, CV benefit');
  }

  // ─── Lifestyle Interventions ──────────────────────────────────────────────
  const lifestyleInterventions =
    'LIFESTYLE INTERVENTIONS (cornerstone of MASLD management): ' +
    '1) Weight loss: ≥5% body weight → reduces steatosis; ≥7–10% → MASH resolution; ≥10% → fibrosis improvement. ' +
    '2) Mediterranean diet: most evidence for MASLD — reduces liver fat and inflammation. ' +
    '3) Physical activity: 150–300 min/week moderate aerobic + resistance training. ' +
    '4) Alcohol: complete abstinence recommended for MASH with fibrosis. ' +
    '5) Fructose/sugar-sweetened beverages: avoid — accelerates hepatic steatosis. ' +
    '6) Coffee: 2–3 cups/day associated with reduced fibrosis progression.';

  // ─── Surveillance Plan ────────────────────────────────────────────────────
  let surveillancePlan = '';
  if (input.hasCirchosis || input.estimatedFibrosisStage === 'F4_cirrhosis') {
    surveillancePlan =
      'Cirrhosis surveillance: ' +
      'HCC surveillance: liver ultrasound ± AFP every 6 months. ' +
      'EGD every 1–3 years for varices. ' +
      'Labs every 3–6 months: CBC, CMP, INR, AFP. ' +
      'MELD score calculation every 3–6 months.';
    nextSteps.push('HCC surveillance: liver ultrasound + AFP every 6 months', 'EGD for variceal screening');
  } else if (fibrosisRisk === 'high') {
    surveillancePlan =
      'Advanced fibrosis (F3) surveillance: ' +
      'FIB-4 + FibroScan every 12 months. ' +
      'Consider HCC surveillance if cirrhosis develops. ' +
      'Hepatology follow-up every 6 months.';
  } else {
    surveillancePlan =
      'Low-intermediate fibrosis: ' +
      'FIB-4 every 1–2 years. ' +
      'Liver ultrasound annually if metabolic risk factors present. ' +
      'Reassess pharmacotherapy candidacy if FIB-4 increases.';
  }

  // ─── Transplant Consideration ─────────────────────────────────────────────
  let transplantConsideration = 'No immediate transplant evaluation indicated.';
  if (input.meldScore !== undefined && input.meldScore >= 15) {
    transplantConsideration =
      `MELD ${input.meldScore} ≥15: liver transplant evaluation recommended. ` +
      'MASLD/MASH is now the leading indication for liver transplant in the US. ' +
      'Transplant outcomes in MASLD are good — 5-year survival ~70%. ' +
      'Cardiometabolic optimization required before transplant listing.';
  } else if (input.hasCirchosis && (input.hasAscites || input.hasHepaticEncephalopathy)) {
    transplantConsideration =
      'Decompensated cirrhosis: hepatology referral for transplant evaluation. ' +
      'MELD score calculation to determine transplant priority.';
  }

  const rationale =
    `MASLD/MASH status: ${input.mashStatus.replace(/_/g, ' ')}. ` +
    `Estimated fibrosis stage: ${input.estimatedFibrosisStage}. ` +
    `FIB-4: ${input.fib4Score?.toFixed(2) ?? 'not calculated'}. ` +
    `Fibrosis risk: ${fibrosisRisk}. ` +
    `Diabetes: ${input.diabetesStatus.replace(/_/g, ' ')}. ` +
    `Cirrhosis: ${input.hasCirchosis ? 'Yes' : 'No'}.`;

  return {
    primaryRecommendation:
      input.hasHCC
        ? 'Hepatocellular carcinoma detected — multidisciplinary liver tumor board review required.'
        : input.hasAscites || input.hasHepaticEncephalopathy
        ? 'Decompensated cirrhosis — urgent hepatology referral and transplant evaluation.'
        : isPharmacotherapyCandidate
        ? 'MASH with significant fibrosis (F2–F3): resmetirom (FDA-approved 2024) + GLP-1 agonist + lifestyle modification.'
        : 'MASLD without significant fibrosis: lifestyle modification, cardiometabolic optimization, annual FIB-4 monitoring.',
    fibrosisAssessment,
    pharmacotherapy,
    liverBiopsyIndication,
    cardiometabolicManagement,
    lifestyleInterventions,
    surveillancePlan,
    transplantConsideration,
    urgentFlags,
    recommendedAgents,
    nextSteps,
    evidenceLevel: 'A',
    rationale,
    references: [
      {
        citation: 'Loomba R, et al. Resmetirom for Nonalcoholic Steatohepatitis with Liver Fibrosis (MAESTRO-NASH). N Engl J Med. 2024;390(6):497-509.',
        pmid: '38324483',
        url: 'https://pubmed.ncbi.nlm.nih.gov/38324483/',
      },
      {
        citation: 'AGA Clinical Practice Update on Nonalcoholic Fatty Liver Disease 2023. Gastroenterology. 2023;165(6):1392-1405.',
        pmid: '37678709',
        url: 'https://pubmed.ncbi.nlm.nih.gov/37678709/',
      },
      {
        citation: 'Rinella ME, et al. AASLD Practice Guidance on the Clinical Assessment and Management of Nonalcoholic Fatty Liver Disease. Hepatology. 2023;77(5):1797-1835.',
        pmid: '36727674',
        url: 'https://pubmed.ncbi.nlm.nih.gov/36727674/',
      },
      {
        citation: 'Sanyal AJ, et al. Pioglitazone, Vitamin E, or Placebo for Nonalcoholic Steatohepatitis (PIVENS). N Engl J Med. 2010;362(18):1675-1685.',
        pmid: '20427778',
        url: 'https://pubmed.ncbi.nlm.nih.gov/20427778/',
      },
      {
        citation: 'Newsome PN, et al. A Placebo-Controlled Trial of Subcutaneous Semaglutide in Nonalcoholic Steatohepatitis. N Engl J Med. 2021;384(12):1113-1124.',
        pmid: '33185364',
        url: 'https://pubmed.ncbi.nlm.nih.gov/33185364/',
      },
    ],
  };
}

// Helper: FIB-4 calculator
export function calculateFIB4(age: number, ast: number, alt: number, platelet: number): number {
  return (age * ast) / (platelet * Math.sqrt(alt));
}
